#!/usr/bin/env python3

import json
import re

# This is a simplified validation script to check if the issues in detection_temp.json match the CWE knowledge base patterns

# Load the CWE database
with open('/workspace/repo/memory/cwe.json', 'r') as f:
    cwe_db = json.load(f)

# Load the findings from detection_temp.json  
with open('/workspace/repo/detection_temp.json', 'r') as f:
    findings = json.load(f)

# Create a mapping for CWE IDs to category, severity and patterns
cwe_mapping = {}
for cwe in cwe_db['cwes']:
    cwe_id = cwe['id']
    cwe_mapping[cwe_id] = {
        'category': cwe['category'],
        'severity': cwe['severity'],
        'patterns': cwe.get('patterns', []),
        'languages': cwe.get('languages', []),
        'examples': cwe.get('examples', {})
    }

# Validate each finding against CWE database
valid_findings = []

for finding in findings:
    filepath = finding['filepath']
    line_number = finding['line_number'] 
    review_comment = finding['review_comment']
    line_snippet = finding['line_snippet']

    # Determine potential CWEs based on review comment
    vuln_type = None

    if 'SQL injection' in review_comment.lower():
        # Check for SQL injection patterns
        if ('user_id' in line_snippet and '+' in line_snippet) or ('SELECT * FROM' in line_snippet):
            if 'user_id' in line_snippet:
                vuln_type = 'CWE-89'

    elif 'command injection' in review_comment.lower() or 'system commands' in review_comment.lower():
        # Check for command injection patterns  
        if 'os.system(' in line_snippet or 'system(' in line_snippet:
            # Look for user input that isn't sanitized
            if ('user_directory' in line_snippet and '+' in line_snippet) or ('+ ' in line_snippet):
                vuln_type = 'CWE-78'

    elif 'xss' in review_comment.lower() or 'cross-site scripting' in review_comment.lower():
        # Check for XSS patterns
        if '{{ device.name }}' in line_snippet:
            vuln_type = 'CWE-79'

    elif 'path traversal' in review_comment.lower() or 'file path' in review_comment.lower():
        # Check for path traversal patterns
        if '/uploads/' in line_snippet and filename in line_snippet:
            vuln_type = 'CWE-22'

    elif 'authentication' in review_comment.lower() or 'password' in review_comment.lower():
        # Check for authentication issues
        if ('user_password == stored_password' in line_snippet) and ('== ' in line_snippet):
            vuln_type = 'CWE-287'  # Improper Authentication

    if vuln_type:
        finding['vuln_type'] = vuln_type
        valid_findings.append(finding)

# Write the filtered findings to comments.json
with open('/workspace/repo/comments.json', 'w') as f:
    json.dump(valid_findings, f, indent=2)

